// src/hoverText.ts
function regionLabel(loc) {
  return `${loc.refName}:${(loc.start + 1).toLocaleString()}-${loc.end.toLocaleString()}`;
}
function edgeHoverText(edge, deletion, nameOf = (id) => id) {
  return deletion ? {
    deletion: {
      bp: `${deletion.bp.toLocaleString()} bp`,
      where: regionLabel(deletion)
    }
  } : {
    ends: `${nameOf(edge.from)}${edge.fromStrand ?? ""} \u2192 ${nameOf(edge.to)}${edge.toStrand ?? ""}`
  };
}

export {
  regionLabel,
  edgeHoverText
};
